    const nav: Tab[] = ['Home', 'Check', 'Records', 'Plan', 'Support']; const navIcon: Record<Tab, string> = { Home: '⌂', Check: '◎', Records: '▤', Plan: '♡', Support: '＋' };
    const go = (next: Tab) => { setTab(next); setShowForm(false); setSelected(null); };
